const fold=s=>String(s||'').toLocaleLowerCase('cs').normalize('NFD').replace(/[\u0300-\u036f]/g,'');
function classify(p){const n=fold(p.name),c=fold(p.cat);if(/saltmaris|dezinfekc/.test(n+' '+c))return 'excluded';if(/mini.?go/.test(n)&&/white|bila|bily/.test(n))return 'excluded';if(/prislusenstvi k difuzerum|doplnky k tycinkovym difuzerum|nahradni dily|servisni dily/.test(c))return 'accessory';
// Servisni komponenty nikdy nejsou vhodny samostatny darek.
if(/rozprasovac|trysk|hadick|hlavic|adapter|napajeci zdroj|napajeci kabel|usb kabel|tesnen|cerpadl|kompresor|ventil|filtr|nahradni dil|nahradni soucast|difuzni tycinky|nahradni tycinky|difuzni lahvick|prazdna lahvick|samostatna lahvick|drzak k difuzeru/.test(n))return 'accessory';
// Samostatne naplne nejsou kompletni darky; naopak "difuzer + napln" je komplet.
if(/nahradni napln|napln do|^napln\b/.test(n) && !/difuzer\s*\+\s*napln|tycinkovy difuzer.*napln/.test(n))return 'accessory';
if(/^(?:napln|nahradni|prazdna|lahvicka|difuzni tycinky|tycinky|prislusenstvi|vzorek aroma|testovaci balicek)\b/.test(n) || /nahradni napln|samostatna napln|prazdna lahvicka/.test(n))return 'accessory';if(/hvac|scenteo|hv small|hv medium|hv large|hv dual|industrial/.test(n))return 'professional';if(c.includes('tycinkov')&&/difuzer/.test(n))return 'reed';if(/darkov|sada|set\b|kazeta/.test(n))return 'set';if(c.includes('prani')||c.includes('textil'))return 'laundry';if(/auto|car|mini.?go|woodvent/.test(n+' '+c))return 'car';if(c.includes('aroma olej'))return 'oil';if(c.includes('difuzer'))return 'device';return 'other'}
