const ranges={'500':[0,500],'1000':[500,1000],'2000':[1000,2000],'5000':[2000,5000],more:[5000,Infinity]},r=ranges[a.budget]||[0,Infinity];const inBudget=p.price>=r[0]&&p.price<=r[1]; if(!inBudget)return -1e6;
if(['excluded','accessory','professional','other'].includes(k))return -1e6;
if(k==='oil'&&a.owns!=='yes')return -1e6;
